[workspace.package]
version = "1.14.0"
edition = "2024"
rust-version = "1.95.0"
authors = ["Tempo Contributors"]
license = "MIT OR Apache-2.0"
homepage = "https://docs.tempo.xyz"
repository = "https://github.com/tempoxyz/tempo"
categories = ["cryptography::cryptocurrencies"]
keywords = ["blockchain", "ethereum", "evm", "payments", "tempo"]
publish = false

[workspace]
exclude = ["crates/nitro-attestation/fuzz"]
members = [
  "bin/tempo",
  "bin/tempo-sidecar",
  "crates/alloy",
  "crates/chainspec",
  "crates/consensus",
  "crates/consensus-config",
  "crates/validator-config",
  "crates/dkg-onchain-artifacts",
  "crates/eyre",
  "crates/ext",
  "crates/evm",
  "crates/hardfork",
  "crates/e2e",
  "crates/faucet",
  "crates/node",
  "crates/nitro-attestation",
  "crates/payload/builder",
  "crates/payload/types",
  "crates/precompiles",
  "crates/precompiles-macros",
  "crates/primitives",
  "crates/contracts",
  "crates/telemetry-util",
  "crates/transaction-pool",
  "crates/revm",
  "crates/state-bloat",
  "xtask",
]

# Resolver 3 is available with edition 2024
resolver = "3"

[workspace.lints]
[workspace.lints.clippy]
dbg_macro = "warn"
manual_string_new = "warn"
uninlined_format_args = "warn"
use_self = "warn"
redundant_clone = "warn"
cast_lossless = "deny"
default_constructed_unit_structs = "allow"

[workspace.lints.rust]
rust_2018_idioms = "warn"
unreachable_pub = "warn"
unused_must_use = "warn"
redundant_lifetimes = "warn"
unnameable_types = "warn"

[workspace.lints.rustdoc]
all = "warn"

# Speed up compilation time for dev builds by reducing emitted debug info.
# NOTE: Debuggers may provide less useful information with this setting.
# Uncomment this section if you're using a debugger.
[profile.dev]
# https://davidlattimore.github.io/posts/2024/02/04/speeding-up-the-rust-edit-build-run-cycle.html
debug = "line-tables-only"
split-debuginfo = "unpacked"

# Meant for testing - all optimizations, but with debug assertions and overflow checks.
[profile.hivetests]
inherits = "test"
opt-level = 3
lto = "thin"

[profile.release]
opt-level = 3
lto = "thin"
debug = "none"
strip = "symbols"
panic = "unwind"
codegen-units = 16

# Use the `--profile profiling` flag to show symbols in release mode.
# e.g. `cargo build --profile profiling`
[profile.profiling]
inherits = "release"
debug = "line-tables-only"
strip = "none"
incremental = true

[profile.bench]
inherits = "maxperf"
debug = "line-tables-only"
strip = "none"

[profile.maxperf]
inherits = "release"
lto = "fat"
codegen-units = 1

# Used by Dockerfile.reproducible to produce a byte-deterministic Linux x86_64
# binary that an external rebuilder can hash-compare against the one published
# on the GitHub release. Diverges from `maxperf` (1) by disabling everything
# that introduces nondeterminism (incremental, debug info) and (2) by switching
# panics from unwind to abort. `panic = "abort"` is chosen for the reproducible
# profile because it strips out unwinding tables and the associated codegen
# paths, which are the most reliable source of byte-level drift between
# toolchain versions and stdlib monomorphizations. The user-facing binary
# (built with `maxperf`) keeps `panic = "unwind"` so production panics still
# produce sane backtraces; this profile is only ever consumed by independent
# rebuilders comparing hashes.
[profile.reproducible]
inherits = "release"
lto = "fat"
codegen-units = 1
strip = "none"
debug = "none"
panic = "abort"
incremental = false

